<script setup lang="ts">
import { computed, ref } from 'vue';
import { CHARACTERS, ITEMS, FAULTS } from '../content';
import { state } from './store';
import Art from './Art.vue';
const props=defineProps<{selected?:string}>();
const chosen=ref(props.selected??'');
const records=computed(()=>[...(state.value.repairHistory??[])].reverse());
const record=computed(()=>records.value.find(r=>r.orderId===chosen.value)??records.value[0]);
const name=(id:string)=>ITEMS.find(i=>i.id===id)?.name??id;
const person=(id:string)=>id==='player'?'自有旧货':id==='examiner'?'资质考核':CHARACTERS.find(c=>c.id===id)?.name??'街区委托';
const kinds={client:'客户维修',own:'自有翻新',exam:'资质考核',final:'联络中枢'};
const operations={clean:'清洁',replace:'拆装修复',calibrate:'校准'};
const repaired=computed(()=>record.value?.steps.filter(step=>step.result!=='miss')??[]);
</script>
<template>
 <section class="repair-archive" aria-label="修复档案">
  <p v-if="!records.length" class="archive-empty">这里会留下每次交付的记录：谁带来的旧物、做过的工序，以及修复后的样子。完成一件工单后再来翻翻。</p>
  <template v-else>
   <nav class="archive-index" aria-label="已完成工单"><button v-for="entry in records" :key="entry.orderId" :data-receipt="entry.orderId" :class="{active:entry.orderId===record?.orderId}" @click="chosen=entry.orderId"><Art :id="entry.definitionId"/><span><strong>{{name(entry.definitionId)}}</strong><small>第 {{entry.day}} 日 · {{person(entry.characterId)}}</small></span><b>✓</b></button></nav>
   <article v-if="record" class="repair-document" :data-record="record.orderId"><header><span>九街工坊 / 工序留档</span><strong>已复检 · 已交付</strong></header><div class="document-object"><Art :id="record.definitionId"/><div><small>{{kinds[record.kind]}}</small><h3>{{name(record.definitionId)}}</h3><p>{{person(record.characterId)}}<span v-if="record.receivedDay"> · 第 {{record.receivedDay}} 日收件</span></p><p>第 {{record.day}} 日完成交付</p></div></div><dl class="document-condition"><div><dt>修前品相</dt><dd>{{record.conditionBefore===undefined?'未记录':record.conditionBefore+'%'}}</dd></div><span>→</span><div><dt>修后品相</dt><dd>{{record.conditionAfter}}%</dd></div><div><dt>{{record.kind==='own'?'自有物品':'实收报酬'}}</dt><dd>{{record.kind==='own'?'已入库':'₡'+record.reward}}</dd></div></dl><h4>这件旧物经过的工序</h4><ol class="document-steps"><li v-for="(step,index) in record.steps" :key="index" :class="{miss:step.result==='miss'}"><span>{{step.result==='miss'?'·':'✓'}}</span><div><strong>{{step.faultId?FAULTS.find(f=>f.id===step.faultId)?.name:step.result==='cleaned'?'表面整理':operations[step.operation]}}</strong><p>{{operations[step.operation]}}<template v-if="step.preserve"> · 修整原件</template> · {{step.result==='miss'?'未解决，随后继续检查':'完成'}}<small>第 {{step.day}} 日 · {{step.hours}} 工时</small></p></div></li></ol><p v-if="repaired.length<record.completedOps" class="document-note">部分早期工序未留档；实际完成 {{record.completedOps}} 次工序。</p><footer>复检确认功能正常，交付时已完成结算。<span>{{record.orderId}}</span></footer></article>
   <p class="archive-limit">保留最近 {{records.length}} 份交付记录，最多 80 份。经营累计案例数继续保留。</p>
  </template>
 </section>
</template>
<style scoped>
