-start;gap:12px;margin:13px 0}.document-steps li>span{font-size:19px;color:#557c53}.document-steps strong{font-size:12px;font-weight:500}.document-steps p{font-size:11px;color:#68775b;margin:6px 0;line-height:1.7}.document-steps small{display:block;font-size:10px;color:#7d8769}.document-steps .miss strong,.document-steps .miss>span{color:#956b48}.repair-document footer{font-size:10px;line-height:1.8;border-top:1px solid #a2a98a;margin-top:24px;padding-top:15px;color:#758062}.repair-document footer span{display:block;font-family:monospace;color:#919779;margin-top:5px}.document-note,.archive-limit,.archive-empty{font-size:11px;line-height:1.8;color:#94ad98}.document-note{color:#788366}.archive-limit{grid-column:1/-1;margin:0}.archive-empty{grid-column:1/-1;padding:24px;background:#193732}
